from pathlib import Path
p=Path(__file__).resolve().parents[1]/'panel/app/templates/server_detail.html'
s=p.read_text()
a='</div>\n\n<section class="traffic-usage-panel">\n'
b='''</div>\n\n<section class="server-live-panel" data-server-live-metrics data-metrics-url="/servers/{{ server.id }}?metrics=1">\n  <div class="server-live-head">\n    <div><span>服务器实时监控</span><small>CPU、内存、硬盘与实时网络速率</small></div>\n    <div class="server-live-status" data-live-status><i></i><span>等待数据</span></div>\n  </div>\n  <div class="server-live-grid">\n    <div class="server-live-item"><div class="server-live-value"><span>CPU 使用率</span><strong data-live-cpu>--</strong></div><div class="server-live-progress" data-live-cpu-progress><span data-live-cpu-bar></span></div><small data-live-cpu-note>等待首次采样</small></div>\n    <div class="server-live-item"><div class="server-live-value"><span>内存使用</span><strong data-live-memory>--</strong></div><div class="server-live-progress" data-live-memory-progress><span data-live-memory-bar></span></div><small data-live-memory-note>--</small></div>\n    <div class="server-live-item"><div class="server-live-value"><span>硬盘使用</span><strong data-live-disk>--</strong></div><div class="server-live-progress" data-live-disk-progress><span data-live-disk-bar></span></div><small data-live-disk-note>--</small></div>\n    <div class="server-live-item server-live-network"><div class="server-live-value"><span>实时网络</span><strong data-live-network-summary>采样中</strong></div><div class="server-live-network-rates"><div><span>↓ 下载</span><strong data-live-rx>--</strong></div><div><span>↑ 上传</span><strong data-live-tx>--</strong></div></div><small>瞬时速率，不等于套餐带宽上限</small></div>\n  </div>\n</section>\n\n<section class="traffic-usage-panel">\n'''
if s.count(a)!=1: raise SystemExit(f'overview anchor {s.count(a)}')
p.write_text(s.replace(a,b,1))
